	for (FieldMapping mapping : parsedFields) {
		if (mapping.isMappedToField()) {
			int index = ArgumentUtils.indexOf(headers, mapping.getFieldName());
			if (index == -1) {
				fieldsNotFound.add(mapping.getFieldName());
				continue;
			}
			fieldOrder[index] = mapping;
